#!/usr/bin/env python3
"""Generate explicit independent Blowfish lanes for the bcrypt batch kernel."""
from pathlib import Path

out = ['''// Copyright 2010 The Go Authors. All rights reserved.
// Use of this source code is governed by a BSD-style
// license that can be found in the LICENSE file.
//
// Code generated by generate.py; DO NOT EDIT.
package bcryptlane

import "encoding/binary"

type state struct {
    p [18]uint32
    s0, s1, s2, s3 [256]uint32
}

func keyWords(key []byte) (words [18]uint32) {
    j := 0
    for i := range words {
        for range 4 {
            words[i] = words[i]<<8 | uint32(key[j])
            j++
            if j == len(key) { j = 0 }
        }
    }
    return
}
''']

def round_lines(n):
    lines = []
    for round in range(1, 17):
        x, y = ('l', 'r') if round % 2 else ('r', 'l')
        for k in range(n):
            lines.append(f'{y}{k} ^= ((st[{k}].s0[byte({x}{k}>>24)] + st[{k}].s1[byte({x}{k}>>16)]) ^ st[{k}].s2[byte({x}{k}>>8)]) + st[{k}].s3[byte({x}{k})] ^ st[{k}].p[{round}]')
    return lines


for n in (1, 2, 3, 4, 5):
    out.append(f'func encrypt{n}(st *[{n}]state, l, r *[{n}]uint32) {{')
    for k in range(n):
        out.append(f'l{k}, r{k} := l[{k}] ^ st[{k}].p[0], r[{k}]')
    # Explicit lanes and rounds let the compiler schedule independent S-box
    # loads without relying on an optimizer to unroll a variable-width loop.
    out.extend(round_lines(n))
    for k in range(n):
        out.append(f'l[{k}], r[{k}] = r{k} ^ st[{k}].p[17], l{k}')
    out.append('}')

    # The initial expansion mixes the salt; expensive rounds use an all-zero
    # block input. Generate both so the hot loop has no per-block salt branch.
    for salted in (False, True):
        name = f'expand{n}' + ('Salt' if salted else '')
        salt_arg = f', salts *[{n}][18]uint32' if salted else ''
        out.append(f'func {name}(st *[{n}]state, words *[{n}][18]uint32{salt_arg}) {{')
        out.append(f'for k := range {n} {{ for i := range 18 {{ st[k].p[i] ^= words[k][i] }} }}')
        if not salted and n > 1:
            # Keep chaining words local across the expensive expansion loops.
            # This removes a call and array load/store round trip per block.
            for k in range(n):
                out.append(f'var l{k}, r{k} uint32')
            for box, length in [('p', 18), ('s0', 256), ('s1', 256), ('s2', 256), ('s3', 256)]:
                out.append(f'for i := 0; i < {length}; i += 2 {{')
                for k in range(n):
                    out.append(f'l{k} ^= st[{k}].p[0]')
                out.extend(round_lines(n))
                for k in range(n):
                    out.append(f'l{k}, r{k} = r{k} ^ st[{k}].p[17], l{k}')
                    out.append(f'st[{k}].{box}[i], st[{k}].{box}[i+1] = l{k}, r{k}')
                out.append('}')
            out.append('}')
            continue
        out.append(f'var l, r [{n}]uint32')
        if salted:
            out.append('saltIndex := 0')
        for box, length in [('p', 18), ('s0', 256), ('s1', 256), ('s2', 256), ('s3', 256)]:
            out.append(f'for i := 0; i < {length}; i += 2 {{')
            if salted:
                out.append(f'for k := range {n} {{ l[k] ^= salts[k][saltIndex & 3]; r[k] ^= salts[k][(saltIndex+1) & 3] }}')
                out.append('saltIndex += 2')
            out.append(f'encrypt{n}(st, &l, &r)')
            out.append(f'for k := range {n} {{ st[k].{box}[i], st[k].{box}[i+1] = l[k], r[k] }}')
            out.append('}')
        out.append('}')

    out.append(f'func Sum{n}(passwords [{n}][]byte, salts [{n}][16]byte, cost uint) (result [{n}][23]byte) {{')
    out.append('if cost < 4 || cost > 16 { panic("bcrypt lane cost must be 4..16") }')
    out.append(f'var st [{n}]state; var keys, saltWords [{n}][18]uint32')
    out.append(f'''for k := range {n} {{
        if len(passwords[k]) > 72 {{ panic("bcrypt lane passwords must be <=72 bytes") }}
        var key [73]byte
        copy(key[:], passwords[k])
        keys[k], saltWords[k] = keyWords(key[:len(passwords[k])+1]), keyWords(salts[k][:])
        st[k] = state{{p: p, s0: s0, s1: s1, s2: s2, s3: s3}}
    }}''')
    out.append(f'expand{n}Salt(&st, &keys, &saltWords)')
    out.append(f'for rounds := 0; rounds < 1<<cost; rounds++ {{ expand{n}(&st, &keys); expand{n}(&st, &saltWords) }}')
    out.append(f'var text [{n}][6]uint32')
    out.append(f'for k := range {n} {{ text[k] = [6]uint32{{0x4f727068,0x65616e42,0x65686f6c,0x64657253,0x63727944,0x6f756274}} }}')
    out.append(f'''for block := range 3 {{
        var l, r [{n}]uint32
        for k := range {n} {{ l[k], r[k] = text[k][2*block], text[k][2*block+1] }}
        for range 64 {{ encrypt{n}(&st, &l, &r) }}
        for k := range {n} {{ text[k][2*block], text[k][2*block+1] = l[k], r[k] }}
    }}
    for k := range {n} {{
        var raw [24]byte
        for i, word := range text[k] {{ binary.BigEndian.PutUint32(raw[i*4:], word) }}
        copy(result[k][:], raw[:23])
    }}
    return
    }}''')

Path(__file__).with_name('lanes_generated.go').write_text('\n'.join(out) + '\n')
